-- New Leaf Hearing Care: add Starkey Omega AI+ and Widex Allure AI (insert only)
-- Each update applies only if the stored page is still exactly what was reviewed.
UPDATE ec_hearing_aids SET content='[{"_type":"block","_key":"k39g","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k39f","text":"Starkey Hearing Aids Available In Colorado","marks":[]}]},{"_type":"block","_key":"nlk001","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"nlk002","text":"Starkey G Series AI","marks":[]}]},{"_type":"block","_key":"nlk003","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"nlk004","text":"Starkey G Series AI combines advanced hearing technology with smart, everyday convenience to help users stay connected and confident throughout the day. Built with intelligent sound processing, these hearing aids automatically adapt to changing environments, making conversations clearer and listening more natural.","marks":[]}]},{"_type":"block","_key":"nlk005","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"nlk006","text":"Designed for people with active and social lifestyles, G Series AI enhances speech understanding while reducing background noise, helping users focus on the sounds that matter most. Its rechargeable options, wireless streaming, and durable construction make it a dependable choice for modern hearing support.","marks":[]}]},{"_type":"block","_key":"nlk007","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"nlk008","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"nlk009","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"nlk010","text":"Advanced AI Sound Processing: Automatically adjusts sound settings for clearer conversations in changing environments.","marks":[]}]},{"_type":"block","_key":"nlk011","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"nlk012","text":"Enhanced Speech Clarity: Helps users better understand speech in noisy places like restaurants and gatherings.","marks":[]}]},{"_type":"block","_key":"nlk013","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"nlk014","text":"Bluetooth Streaming Connectivity: Stream phone calls, music, TV audio, and more directly from compatible devices.","marks":[]}]},{"_type":"block","_key":"nlk015","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"nlk016","text":"Rechargeable All-Day Power: Reliable battery performance designed to last throughout the day.","marks":[]}]},{"_type":"block","_key":"nlk017","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"nlk018","text":"Personalized Listening Experience: AI technology learns and adapts to your listening preferences over time.","marks":[]}]},{"_type":"block","_key":"nlk019","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"nlk020","text":"Smartphone App Compatibility: Easily adjust settings, volume, and sound preferences through the Starkey app.","marks":[]}]},{"_type":"block","_key":"q4s000","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"q4s001","text":"Starkey Omega AI+","marks":[]}]},{"_type":"block","_key":"q4s002","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"q4s003","text":"Starkey Omega AI+ is Starkey’s newest premium hearing aid family, released in fall 2026 as the successor to Omega AI. It runs on the new G4 Gen AI Neuro Processor, which uses a brain-inspired design with several deep neural networks (DNNs) to process sound quickly and naturally while using very little power. It’s built for people who want clear speech in any setting along with a long list of everyday smart features.","marks":[]}]},{"_type":"block","_key":"q4s004","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"q4s005","text":"Omega AI+ comes in rechargeable receiver-in-canal (RIC) styles and custom in-ear models, including a new line of tiny custom non-wireless devices. It offers up to 51 hours of battery life, a waterproof design, and the new StarLink Charger 3.0. Through the My Starkey app, wearers also get health and convenience features.","marks":[]}]},{"_type":"block","_key":"q4s006","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"q4s007","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"q4s008","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"q4s009","text":"G4 Gen AI Neuro Processor: A brain-inspired, multi-DNN chip that processes sound faster and more naturally while saving battery power.","marks":[]}],"listItem":"bullet","level":1},{"_type":"block","_key":"q4s00a","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"q4s00b","text":"DNN Dual Compressor: A balance of fast compression for clearer speech and slow compression for richer sound quality.","marks":[]}],"listItem":"bullet","level":1},{"_type":"block","_key":"q4s00c","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"q4s00d","text":"Always-on Edge Mode: Starkey’s AI feature for speech clarity and noise control can now stay on by default, so wearers get the benefit without pressing a button.","marks":[]}],"listItem":"bullet","level":1},{"_type":"block","_key":"q4s00e","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"q4s00f","text":"Sleep Quality Tracking: RIC wearers get a nightly sleep score with insights on sleep cycles and body position through the My Starkey app.","marks":[]}],"listItem":"bullet","level":1},{"_type":"block","_key":"q4s00g","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"q4s00h","text":"Hearing Aids Left Behind alerts: The app notifies wearers if they walk away without their hearing aids.","marks":[]}],"listItem":"bullet","level":1},{"_type":"block","_key":"q4s00i","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"q4s00j","text":"All-day rechargeable power: Up to 51 hours of battery life per charge, paired with the redesigned StarLink Charger 3.0.","marks":[]}],"listItem":"bullet","level":1},{"_type":"block","_key":"k39i","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k39h","text":"Starkey Omega AI","marks":[]}]},{"_type":"block","_key":"k39k","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k39j","text":"Starkey Omega AI is built with industry-leading technology that gives users powerful sound clarity and day-long comfort. Its advanced AI system constantly analyzes your surroundings to help you hear speech clearly, stay aware of important sounds, and move through different environments with ease.","marks":[]}]},{"_type":"block","_key":"k39m","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k39l","text":"If you struggle with hearing in noisy places, Omega AI’s Edge Mode+ provides on-demand help by sharpening speech instantly, even in challenging spaces like restaurants, shopping centers, or family gatherings.","marks":[]}]},{"_type":"block","_key":"k39o","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k39n","text":"These hearing aids are also designed for durability. With a 10x more durable waterproof coating, Omega AI can handle rain, sweat, and everyday wear without worry. Rechargeable options give all-day power, keeping you connected from morning to night.","marks":[]}]},{"_type":"block","_key":"k39q","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k39p","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"k39s","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k39r","text":"Edge Mode+: Boosts speech clarity during tough listening moments.","marks":[]}]},{"_type":"block","_key":"k39u","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k39t","text":"Waterproof & Everyday-Proof: Designed for active lifestyles and all-day comfort.","marks":[]}]},{"_type":"block","_key":"k39w","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k39v","text":"Auracast™ & LE Audio Ready: Allows streaming from TVs, smartphones, public announcement systems, and more.","marks":[]}]},{"_type":"block","_key":"k39y","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k39x","text":"Starkey App (Now Powered by Gen AI): Use TeleHear AI for instant, AI-based sound adjustments.","marks":[]}]},{"_type":"block","_key":"k3a0","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k39z","text":"Starkey Signature Series","marks":[]}]},{"_type":"block","_key":"k3a2","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3a1","text":"The Starkey Signature Series gives you amazing sound in hearing aids that are super tiny and almost invisible. They are custom-made to fit inside your ear, so no one can tell you’re wearing them. You’ll hear your friends, family, and the world around you clearly, without anyone knowing why. Whether you want rechargeable, adjustable, or the smallest size possible, there’s a signature style just for you.","marks":[]}]},{"_type":"block","_key":"k3a4","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3a3","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"k3a6","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3a5","text":"Discreet: Nearly invisible and fits deep in your ear.","marks":[]}]},{"_type":"block","_key":"k3a8","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3a7","text":"Natural Sound: Clear, lifelike sound so you can enjoy every moment.","marks":[]}]},{"_type":"block","_key":"k3aa","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3a9","text":"Rechargeable: Up to 38 hours of power—no tiny batteries to change.","marks":[]}]},{"_type":"block","_key":"k3ac","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3ab","text":"Waterproof: Designed to handle water up to 1 meter deep.","marks":[]}]},{"_type":"block","_key":"k3ae","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3ad","text":"Custom Fit: Made just for your ears for all-day comfort and security.","marks":[]}]},{"_type":"block","_key":"k3ag","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k3af","text":"Starkey Edge AI","marks":[]}]},{"_type":"block","_key":"k3ai","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3ah","text":"Starkey Edge AI hearing aids use artificial intelligence (AI) to improve sound quality and make hearing easier. A powerful smart chip inside these hearing aids quickly recognizes different sounds and reduces background noise, so users can focus on what matters most.","marks":[]}]},{"_type":"block","_key":"k3ak","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3aj","text":"The Edge AI automatically adjusts to changing environments, making speech 30% clearer than previous models. Whether in a crowded restaurant or at home, these hearing aids help users hear voices more clearly.","marks":[]}]},{"_type":"block","_key":"k3am","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3al","text":"​Unique Features:","marks":[]}]},{"_type":"block","_key":"k3ao","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3an","text":"Built To Last: Waterproof up to 1 meter and resistant to sweat, these hearing aids are designed to handle daily activities with ease.","marks":[]}]},{"_type":"block","_key":"k3aq","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3ap","text":"Reliable Bluetooth Connection: Edge AI uses advanced Bluetooth technology for a stronger, more stable connection to smartphones and other devices. It also supports Auracast™, allowing users to connect to TVs and public sound systems effortlessly.","marks":[]}]},{"_type":"block","_key":"k3as","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3ar","text":"Health & Safety Benefits: These hearing aids include balance exercises to support stability. They also have fall detection and alert features to keep users safe.","marks":[]}]},{"_type":"block","_key":"k3au","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3at","text":"Simple App Control: The My Starkey app makes it easy to adjust settings, control volume, stream calls, set reminders, and locate lost hearing aids. It works with both smartphones and Apple Watch for convenience.","marks":[]}]},{"_type":"block","_key":"k3aw","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k3av","text":"Starkey Genesis AI RIC","marks":[]}]},{"_type":"block","_key":"k3ay","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3ax","text":"Starkey’s newest Genesis AI platform released its Neuro Sound Technology, which enables you to hear soft sounds without noise, distinguish words and speech more naturally, and significantly reduce your listening effort.","marks":[]}]},{"_type":"block","_key":"k3b0","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3az","text":"Starkey’s advanced technology utilizes complex pattern recognition with advanced machine learning; meaning it adapts to more listening situations than ever before. Additional features like EdgeMode use AI technology to let patients optimize sound quality at their fingertips to improve their listening needs.","marks":[]}]},{"_type":"block","_key":"k3b2","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3b1","text":"Starkey Genesis AI receiver-in-the-canal (RIC) products are appropriate for minimal to severe hearing loss. There is an option for either a rechargeable or a size 312 disposable battery. Their rechargeable technology is the longest-lasting rechargeable RIC on the market, holding up to 51 hours of use on a single charge and up to 3 hours of use on a 7-minute charge!","marks":[]}]},{"_type":"block","_key":"k3b4","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3b3","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"k3b6","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3b5","text":"Waterproof: Starkey’s Pro8 HydraShield features eight protective layers specifically targeting ingress and corrosion — ensuring Genesis AI devices can withstand sweat, rain, dirt, drops, and dunks.","marks":[]}]},{"_type":"block","_key":"k3b8","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3b7","text":"Bluetooth Connectivity: The My Starkey app pairs with Genesis AI hearing aids to help you enjoy greater listening moments, improved well-being, and easier everyday living — all from the palm of your hand. Enjoy convenient features such as adjusting hearing aid settings, streaming calls, and even finding lost hearing aids.","marks":[]}]},{"_type":"block","_key":"k3ba","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3b9","text":"Remote Support: TeleHear is a remote telehealth solution that keeps you connected when you can’t make it to the office. This assists your concerns on demand with remote adjustments via video chat.","marks":[]}]},{"_type":"block","_key":"k3bc","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3bb","text":"Customizable Tinnitus Relief: Multiflex Tinnitus Technology enables superior flexibility in fine-tuning a relieving sound stimulus for each individual.","marks":[]}]},{"_type":"block","_key":"k3be","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k3bd","text":"Starkey Genesis AI ITE","marks":[]}]},{"_type":"block","_key":"k3bg","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3bf","text":"Not all hearing aids are created the same. Starkey values the importance of a fitting unique to each individual, and their newest Genesis AI in-the-ear (ITE) products are no exception. The advanced sound processor uses technology with a unique on-board Deep Neural Network (DNN) that mimics the cerebral cortex of the human brain. The end goal is to provide the most natural, complete picture of your listening environment.","marks":[]}]},{"_type":"block","_key":"k3bi","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3bh","text":"Starkey Genesis AI ITE products are appropriate for mild to severe to profound hearing loss. There is an option for either a rechargeable or a disposable battery. The most recent Genesis AI","marks":[]}]},{"_type":"block","_key":"k3bk","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3bj","text":"ITE devices offer the industry’s smallest new wireless CIC. This allows for the most discrete fit without compromising sound quality.","marks":[]}]},{"_type":"block","_key":"k3bm","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3bl","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"k3bo","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3bn","text":"Waterproof: Starkey’s Pro8 HydraShield features eight protective layers specifically targeting ingress and corrosion — ensuring Genesis AI devices can withstand sweat, rain, dirt, drops, and dunks.","marks":[]}]},{"_type":"block","_key":"k3bq","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3bp","text":"Bluetooth Connectivity: The My Starkey app pairs with Genesis AI hearing aids to help you enjoy greater listening moments, improved well-being, and easier everyday living — all from the palm of your hand. Enjoy convenient features such as adjusting hearing aid settings, streaming calls, and even finding lost hearing aids.","marks":[]}]},{"_type":"block","_key":"k3bs","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3br","text":"Remote Support: TeleHear is a remote telehealth solution that keeps you connected when you can’t make it to the office. This assists your concerns on demand with remote adjustments via video chat.","marks":[]}]},{"_type":"block","_key":"k3bu","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3bt","text":"Customizable Tinnitus Relief: Multiflex Tinnitus Technology enables superior flexibility in fine-tuning a relieving sound stimulus for each individual.","marks":[]}]},{"_type":"block","_key":"k3bw","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k3bv","text":"Starkey CROS","marks":[]}]},{"_type":"block","_key":"k3by","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3bx","text":"Starkey’s wireless contralateral routing of the signal (CROS) product takes audio information from an ear-level microphone and wirelessly transmits it to the opposite ear. The CROS/BiCROS devices pair with a Starkey hearing aid on the better hearing ear. With 55 million personalized adjustments every hour, they aim to provide an immersive listening experience.","marks":[]}]},{"_type":"block","_key":"k3c0","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3bz","text":"The Starkey CROS is designed for individuals with one-sided hearing loss, or single-sided deafness (SSD). The device can be fitted as either a true CROS or BiCROS (hearing loss is also in the better hearing ear).","marks":[]}]},{"_type":"block","_key":"k3c2","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3c1","text":"The CROS is available with the Genesis AI family product line in addition to previous generation models.","marks":[]}]},{"_type":"block","_key":"k3c4","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3c3","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"k3c6","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3c5","text":"Wireless Audio Transmission: Seamlessly transmits audio from one ear to the other, ensuring clear and balanced hearing.","marks":[]}]},{"_type":"block","_key":"k3c8","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3c7","text":"Personalized Adjustments: Delivers 55 million personalized adjustments every hour for an immersive listening experience.","marks":[]}]},{"_type":"block","_key":"k3ca","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3c9","text":"Versatile Fitting Options: Can be fitted as either a true CROS or BiCROS, catering to various hearing loss needs.","marks":[]}]},{"_type":"block","_key":"k3cc","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3cb","text":"Advanced Compatibility: Available with the Genesis AI family product line and previous generation models.","marks":[]}]},{"_type":"block","_key":"k3ce","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k3cd","text":"Starkey Evolv AI BTE","marks":[]}]},{"_type":"block","_key":"k3cg","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3cf","text":"Starkey offers a traditional behind-the-ear (BTE) style with innovative sound processing. The Evolv AI technology is capable of 55 million automatic adjustments per hour and improves reduction in bothersome noise levels, including wind and machine noise. Additional features like Edge Mode offer even clearer sound in cars and other vehicles.","marks":[]}]},{"_type":"block","_key":"k3ci","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3ch","text":"Starkey Evolv AI behind-the-ear (BTE) products are appropriate for mild to severe-to-profound hearing losses. There is an option for either a rechargeable or a disposable battery.","marks":[]}]},{"_type":"block","_key":"k3ck","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3cj","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"k3cm","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3cl","text":"Bluetooth Connectivity: The Thrive Hearing Control app pairs with Evolv AI BTE hearing aids to help you enjoy greater listening moments, improved well-being, and easier everyday living — all from the palm of your hand. Enjoy convenient features such as adjusting hearing aid settings, streaming calls, and even finding lost hearing aids.","marks":[]}]},{"_type":"block","_key":"k3co","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3cn","text":"Remote Support: TeleHear is a remote telehealth solution that keeps you connected when you can’t make it to the office. This assists your concerns on demand with remote adjustments via video chat.","marks":[]}]},{"_type":"block","_key":"k3cq","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3cp","text":"Customizable Tinnitus Relief: Multiflex Tinnitus Technology enables superior flexibility in fine-tuning a relieving sound stimulus for each individual.","marks":[]}]},{"_type":"block","_key":"k3cs","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k3cr","text":"Starkey Evolv AI Power Plus BTE","marks":[]}]},{"_type":"block","_key":"k3cu","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3ct","text":"Featuring all the benefits and sophisticated technology of the Evolv AI BTE, the Power Plus BTE provides power for the most significant hearing losses.","marks":[]}]},{"_type":"block","_key":"k3cw","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3cv","text":"The Starkey Evolv AI Power Plus BTE model is appropriate for severe to profound hearing losses. This model is available in a size 13 disposable battery.","marks":[]}]},{"_type":"block","_key":"k3cy","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3cx","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"k3d0","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3cz","text":"Bluetooth Connectivity: The Thrive Hearing Control app pairs with Evolv AI Power Plus BTE hearing aids to help you enjoy greater listening moments, improved well-being, and easier everyday living — all from the palm of your hand. Enjoy convenient features such as adjusting hearing aid settings, streaming calls, and even finding lost hearing aids.","marks":[]}]},{"_type":"block","_key":"k3d2","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3d1","text":"Remote Support: TeleHear is a remote telehealth solution that keeps you connected when you can’t make it to the office. This assists your concerns on demand with remote adjustments via video chat.","marks":[]}]},{"_type":"block","_key":"k3d4","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3d3","text":"Customizable Tinnitus Relief: Multiflex Tinnitus Technology enables superior  flexibility in fine-tuning a relieving sound stimulus for each individual.","marks":[]}]},{"_type":"block","_key":"k3d6","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k3d5","text":"Assistive Listening Devices & Technology by Starkey","marks":[]}]},{"_type":"block","_key":"k3d8","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3d7","text":"Mini Remote Microphone","marks":[]}]},{"_type":"block","_key":"k3da","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3d9","text":"Remote Mic +","marks":[]}]},{"_type":"block","_key":"k3dc","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3db","text":"Remote Control 2.0","marks":[]}]},{"_type":"block","_key":"k3de","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3dd","text":"Table Microphone","marks":[]}]},{"_type":"block","_key":"k3dg","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3df","text":"TV Streamer","marks":[]}]},{"_type":"block","_key":"k3di","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k3dh","text":"Older Starkey Hearing Aid Models Supported By New Leaf Hearing Care In Colorado","marks":[]}]},{"_type":"block","_key":"k3dk","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3dj","text":"These hearing aid models may still be supported for hearing aid servicing and repair by New Leaf Hearing Care in Arvada, CO and Littleton, CO. Please contact us for more information.","marks":[]}]},{"_type":"block","_key":"k3dm","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3dl","text":"Starkey Picasso","marks":[]}]},{"_type":"block","_key":"k3do","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3dn","text":"Starkey Livio","marks":[]}]},{"_type":"block","_key":"k3dq","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3dp","text":"Starkey Muse iQ","marks":[]}]},{"_type":"block","_key":"k3ds","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3dr","text":"Starkey Halo iQ","marks":[]}]},{"_type":"block","_key":"k3du","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3dt","text":"Starkey Halo 2","marks":[]}]},{"_type":"block","_key":"k3dw","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3dv","text":"Starkey Halo","marks":[]}]},{"_type":"block","_key":"k3dy","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k3dx","text":"Frequently Asked Questions About Starkey Hearing Aids","marks":[]}]},{"_type":"block","_key":"k3e0","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k3dz","text":"What are the tech levels of Starkey Genesis AI?","marks":[]}]},{"_type":"block","_key":"k3e2","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3e1","text":"There are four technology levels for most of the available styles (24, 20, 16, 12) ranging from highest to lowest technology level, respectively. A contralateral routing of signal (CROS) model is also available for those with severe single-sided hearing loss.","marks":[]}]},{"_type":"block","_key":"k3e4","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k3e3","text":"What app does Starkey Genesis AI use?","marks":[]}]},{"_type":"block","_key":"k3e6","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3e5","text":"The My Starkey app pairs with Genesis AI hearing aids to help you enjoy greater listening moments, improved well-being, and easier everyday living — all at the convenience of your fingertips. User-friendly and easy to read, it delivers benefits that allow you to hear your best in a multitude of listening scenarios.","marks":[]}]},{"_type":"block","_key":"k3e8","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k3e7","text":"What is the life expectancy of a Starkey hearing aid?","marks":[]}]},{"_type":"block","_key":"k3ea","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3e9","text":"Generally speaking, in-the-ear hearing aids tend to last up to five years, while behind-the-ear hearing aids typically last five to six years. Largely, it depends on how well you take care of your hearing aids. Some patients will decide to upgrade their hearing aids prior to this time, as newer technology is routinely released and may provide greater benefits. An audiologist will be able to guide you in deciding when an upgrade is necessary.","marks":[]}]}]', updated_at=datetime('now') WHERE slug='starkey-hearing-aids' AND content='[{"_type":"block","_key":"k39g","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k39f","text":"Starkey Hearing Aids Available In Colorado","marks":[]}]},{"_type":"block","_key":"nlk001","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"nlk002","text":"Starkey G Series AI","marks":[]}]},{"_type":"block","_key":"nlk003","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"nlk004","text":"Starkey G Series AI combines advanced hearing technology with smart, everyday convenience to help users stay connected and confident throughout the day. Built with intelligent sound processing, these hearing aids automatically adapt to changing environments, making conversations clearer and listening more natural.","marks":[]}]},{"_type":"block","_key":"nlk005","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"nlk006","text":"Designed for people with active and social lifestyles, G Series AI enhances speech understanding while reducing background noise, helping users focus on the sounds that matter most. Its rechargeable options, wireless streaming, and durable construction make it a dependable choice for modern hearing support.","marks":[]}]},{"_type":"block","_key":"nlk007","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"nlk008","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"nlk009","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"nlk010","text":"Advanced AI Sound Processing: Automatically adjusts sound settings for clearer conversations in changing environments.","marks":[]}]},{"_type":"block","_key":"nlk011","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"nlk012","text":"Enhanced Speech Clarity: Helps users better understand speech in noisy places like restaurants and gatherings.","marks":[]}]},{"_type":"block","_key":"nlk013","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"nlk014","text":"Bluetooth Streaming Connectivity: Stream phone calls, music, TV audio, and more directly from compatible devices.","marks":[]}]},{"_type":"block","_key":"nlk015","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"nlk016","text":"Rechargeable All-Day Power: Reliable battery performance designed to last throughout the day.","marks":[]}]},{"_type":"block","_key":"nlk017","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"nlk018","text":"Personalized Listening Experience: AI technology learns and adapts to your listening preferences over time.","marks":[]}]},{"_type":"block","_key":"nlk019","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"nlk020","text":"Smartphone App Compatibility: Easily adjust settings, volume, and sound preferences through the Starkey app.","marks":[]}]},{"_type":"block","_key":"k39i","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k39h","text":"Starkey Omega AI","marks":[]}]},{"_type":"block","_key":"k39k","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k39j","text":"Starkey Omega AI is built with industry-leading technology that gives users powerful sound clarity and day-long comfort. Its advanced AI system constantly analyzes your surroundings to help you hear speech clearly, stay aware of important sounds, and move through different environments with ease.","marks":[]}]},{"_type":"block","_key":"k39m","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k39l","text":"If you struggle with hearing in noisy places, Omega AI’s Edge Mode+ provides on-demand help by sharpening speech instantly, even in challenging spaces like restaurants, shopping centers, or family gatherings.","marks":[]}]},{"_type":"block","_key":"k39o","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k39n","text":"These hearing aids are also designed for durability. With a 10x more durable waterproof coating, Omega AI can handle rain, sweat, and everyday wear without worry. Rechargeable options give all-day power, keeping you connected from morning to night.","marks":[]}]},{"_type":"block","_key":"k39q","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k39p","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"k39s","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k39r","text":"Edge Mode+: Boosts speech clarity during tough listening moments.","marks":[]}]},{"_type":"block","_key":"k39u","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k39t","text":"Waterproof & Everyday-Proof: Designed for active lifestyles and all-day comfort.","marks":[]}]},{"_type":"block","_key":"k39w","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k39v","text":"Auracast™ & LE Audio Ready: Allows streaming from TVs, smartphones, public announcement systems, and more.","marks":[]}]},{"_type":"block","_key":"k39y","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k39x","text":"Starkey App (Now Powered by Gen AI): Use TeleHear AI for instant, AI-based sound adjustments.","marks":[]}]},{"_type":"block","_key":"k3a0","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k39z","text":"Starkey Signature Series","marks":[]}]},{"_type":"block","_key":"k3a2","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3a1","text":"The Starkey Signature Series gives you amazing sound in hearing aids that are super tiny and almost invisible. They are custom-made to fit inside your ear, so no one can tell you’re wearing them. You’ll hear your friends, family, and the world around you clearly, without anyone knowing why. Whether you want rechargeable, adjustable, or the smallest size possible, there’s a signature style just for you.","marks":[]}]},{"_type":"block","_key":"k3a4","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3a3","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"k3a6","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3a5","text":"Discreet: Nearly invisible and fits deep in your ear.","marks":[]}]},{"_type":"block","_key":"k3a8","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3a7","text":"Natural Sound: Clear, lifelike sound so you can enjoy every moment.","marks":[]}]},{"_type":"block","_key":"k3aa","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3a9","text":"Rechargeable: Up to 38 hours of power—no tiny batteries to change.","marks":[]}]},{"_type":"block","_key":"k3ac","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3ab","text":"Waterproof: Designed to handle water up to 1 meter deep.","marks":[]}]},{"_type":"block","_key":"k3ae","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3ad","text":"Custom Fit: Made just for your ears for all-day comfort and security.","marks":[]}]},{"_type":"block","_key":"k3ag","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k3af","text":"Starkey Edge AI","marks":[]}]},{"_type":"block","_key":"k3ai","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3ah","text":"Starkey Edge AI hearing aids use artificial intelligence (AI) to improve sound quality and make hearing easier. A powerful smart chip inside these hearing aids quickly recognizes different sounds and reduces background noise, so users can focus on what matters most.","marks":[]}]},{"_type":"block","_key":"k3ak","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3aj","text":"The Edge AI automatically adjusts to changing environments, making speech 30% clearer than previous models. Whether in a crowded restaurant or at home, these hearing aids help users hear voices more clearly.","marks":[]}]},{"_type":"block","_key":"k3am","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3al","text":"​Unique Features:","marks":[]}]},{"_type":"block","_key":"k3ao","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3an","text":"Built To Last: Waterproof up to 1 meter and resistant to sweat, these hearing aids are designed to handle daily activities with ease.","marks":[]}]},{"_type":"block","_key":"k3aq","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3ap","text":"Reliable Bluetooth Connection: Edge AI uses advanced Bluetooth technology for a stronger, more stable connection to smartphones and other devices. It also supports Auracast™, allowing users to connect to TVs and public sound systems effortlessly.","marks":[]}]},{"_type":"block","_key":"k3as","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3ar","text":"Health & Safety Benefits: These hearing aids include balance exercises to support stability. They also have fall detection and alert features to keep users safe.","marks":[]}]},{"_type":"block","_key":"k3au","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3at","text":"Simple App Control: The My Starkey app makes it easy to adjust settings, control volume, stream calls, set reminders, and locate lost hearing aids. It works with both smartphones and Apple Watch for convenience.","marks":[]}]},{"_type":"block","_key":"k3aw","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k3av","text":"Starkey Genesis AI RIC","marks":[]}]},{"_type":"block","_key":"k3ay","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3ax","text":"Starkey’s newest Genesis AI platform released its Neuro Sound Technology, which enables you to hear soft sounds without noise, distinguish words and speech more naturally, and significantly reduce your listening effort.","marks":[]}]},{"_type":"block","_key":"k3b0","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3az","text":"Starkey’s advanced technology utilizes complex pattern recognition with advanced machine learning; meaning it adapts to more listening situations than ever before. Additional features like EdgeMode use AI technology to let patients optimize sound quality at their fingertips to improve their listening needs.","marks":[]}]},{"_type":"block","_key":"k3b2","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3b1","text":"Starkey Genesis AI receiver-in-the-canal (RIC) products are appropriate for minimal to severe hearing loss. There is an option for either a rechargeable or a size 312 disposable battery. Their rechargeable technology is the longest-lasting rechargeable RIC on the market, holding up to 51 hours of use on a single charge and up to 3 hours of use on a 7-minute charge!","marks":[]}]},{"_type":"block","_key":"k3b4","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3b3","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"k3b6","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3b5","text":"Waterproof: Starkey’s Pro8 HydraShield features eight protective layers specifically targeting ingress and corrosion — ensuring Genesis AI devices can withstand sweat, rain, dirt, drops, and dunks.","marks":[]}]},{"_type":"block","_key":"k3b8","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3b7","text":"Bluetooth Connectivity: The My Starkey app pairs with Genesis AI hearing aids to help you enjoy greater listening moments, improved well-being, and easier everyday living — all from the palm of your hand. Enjoy convenient features such as adjusting hearing aid settings, streaming calls, and even finding lost hearing aids.","marks":[]}]},{"_type":"block","_key":"k3ba","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3b9","text":"Remote Support: TeleHear is a remote telehealth solution that keeps you connected when you can’t make it to the office. This assists your concerns on demand with remote adjustments via video chat.","marks":[]}]},{"_type":"block","_key":"k3bc","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3bb","text":"Customizable Tinnitus Relief: Multiflex Tinnitus Technology enables superior flexibility in fine-tuning a relieving sound stimulus for each individual.","marks":[]}]},{"_type":"block","_key":"k3be","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k3bd","text":"Starkey Genesis AI ITE","marks":[]}]},{"_type":"block","_key":"k3bg","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3bf","text":"Not all hearing aids are created the same. Starkey values the importance of a fitting unique to each individual, and their newest Genesis AI in-the-ear (ITE) products are no exception. The advanced sound processor uses technology with a unique on-board Deep Neural Network (DNN) that mimics the cerebral cortex of the human brain. The end goal is to provide the most natural, complete picture of your listening environment.","marks":[]}]},{"_type":"block","_key":"k3bi","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3bh","text":"Starkey Genesis AI ITE products are appropriate for mild to severe to profound hearing loss. There is an option for either a rechargeable or a disposable battery. The most recent Genesis AI","marks":[]}]},{"_type":"block","_key":"k3bk","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3bj","text":"ITE devices offer the industry’s smallest new wireless CIC. This allows for the most discrete fit without compromising sound quality.","marks":[]}]},{"_type":"block","_key":"k3bm","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3bl","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"k3bo","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3bn","text":"Waterproof: Starkey’s Pro8 HydraShield features eight protective layers specifically targeting ingress and corrosion — ensuring Genesis AI devices can withstand sweat, rain, dirt, drops, and dunks.","marks":[]}]},{"_type":"block","_key":"k3bq","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3bp","text":"Bluetooth Connectivity: The My Starkey app pairs with Genesis AI hearing aids to help you enjoy greater listening moments, improved well-being, and easier everyday living — all from the palm of your hand. Enjoy convenient features such as adjusting hearing aid settings, streaming calls, and even finding lost hearing aids.","marks":[]}]},{"_type":"block","_key":"k3bs","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3br","text":"Remote Support: TeleHear is a remote telehealth solution that keeps you connected when you can’t make it to the office. This assists your concerns on demand with remote adjustments via video chat.","marks":[]}]},{"_type":"block","_key":"k3bu","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3bt","text":"Customizable Tinnitus Relief: Multiflex Tinnitus Technology enables superior flexibility in fine-tuning a relieving sound stimulus for each individual.","marks":[]}]},{"_type":"block","_key":"k3bw","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k3bv","text":"Starkey CROS","marks":[]}]},{"_type":"block","_key":"k3by","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3bx","text":"Starkey’s wireless contralateral routing of the signal (CROS) product takes audio information from an ear-level microphone and wirelessly transmits it to the opposite ear. The CROS/BiCROS devices pair with a Starkey hearing aid on the better hearing ear. With 55 million personalized adjustments every hour, they aim to provide an immersive listening experience.","marks":[]}]},{"_type":"block","_key":"k3c0","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3bz","text":"The Starkey CROS is designed for individuals with one-sided hearing loss, or single-sided deafness (SSD). The device can be fitted as either a true CROS or BiCROS (hearing loss is also in the better hearing ear).","marks":[]}]},{"_type":"block","_key":"k3c2","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3c1","text":"The CROS is available with the Genesis AI family product line in addition to previous generation models.","marks":[]}]},{"_type":"block","_key":"k3c4","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3c3","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"k3c6","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3c5","text":"Wireless Audio Transmission: Seamlessly transmits audio from one ear to the other, ensuring clear and balanced hearing.","marks":[]}]},{"_type":"block","_key":"k3c8","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3c7","text":"Personalized Adjustments: Delivers 55 million personalized adjustments every hour for an immersive listening experience.","marks":[]}]},{"_type":"block","_key":"k3ca","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3c9","text":"Versatile Fitting Options: Can be fitted as either a true CROS or BiCROS, catering to various hearing loss needs.","marks":[]}]},{"_type":"block","_key":"k3cc","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3cb","text":"Advanced Compatibility: Available with the Genesis AI family product line and previous generation models.","marks":[]}]},{"_type":"block","_key":"k3ce","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k3cd","text":"Starkey Evolv AI BTE","marks":[]}]},{"_type":"block","_key":"k3cg","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3cf","text":"Starkey offers a traditional behind-the-ear (BTE) style with innovative sound processing. The Evolv AI technology is capable of 55 million automatic adjustments per hour and improves reduction in bothersome noise levels, including wind and machine noise. Additional features like Edge Mode offer even clearer sound in cars and other vehicles.","marks":[]}]},{"_type":"block","_key":"k3ci","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3ch","text":"Starkey Evolv AI behind-the-ear (BTE) products are appropriate for mild to severe-to-profound hearing losses. There is an option for either a rechargeable or a disposable battery.","marks":[]}]},{"_type":"block","_key":"k3ck","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3cj","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"k3cm","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3cl","text":"Bluetooth Connectivity: The Thrive Hearing Control app pairs with Evolv AI BTE hearing aids to help you enjoy greater listening moments, improved well-being, and easier everyday living — all from the palm of your hand. Enjoy convenient features such as adjusting hearing aid settings, streaming calls, and even finding lost hearing aids.","marks":[]}]},{"_type":"block","_key":"k3co","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3cn","text":"Remote Support: TeleHear is a remote telehealth solution that keeps you connected when you can’t make it to the office. This assists your concerns on demand with remote adjustments via video chat.","marks":[]}]},{"_type":"block","_key":"k3cq","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3cp","text":"Customizable Tinnitus Relief: Multiflex Tinnitus Technology enables superior flexibility in fine-tuning a relieving sound stimulus for each individual.","marks":[]}]},{"_type":"block","_key":"k3cs","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k3cr","text":"Starkey Evolv AI Power Plus BTE","marks":[]}]},{"_type":"block","_key":"k3cu","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3ct","text":"Featuring all the benefits and sophisticated technology of the Evolv AI BTE, the Power Plus BTE provides power for the most significant hearing losses.","marks":[]}]},{"_type":"block","_key":"k3cw","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3cv","text":"The Starkey Evolv AI Power Plus BTE model is appropriate for severe to profound hearing losses. This model is available in a size 13 disposable battery.","marks":[]}]},{"_type":"block","_key":"k3cy","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3cx","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"k3d0","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3cz","text":"Bluetooth Connectivity: The Thrive Hearing Control app pairs with Evolv AI Power Plus BTE hearing aids to help you enjoy greater listening moments, improved well-being, and easier everyday living — all from the palm of your hand. Enjoy convenient features such as adjusting hearing aid settings, streaming calls, and even finding lost hearing aids.","marks":[]}]},{"_type":"block","_key":"k3d2","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3d1","text":"Remote Support: TeleHear is a remote telehealth solution that keeps you connected when you can’t make it to the office. This assists your concerns on demand with remote adjustments via video chat.","marks":[]}]},{"_type":"block","_key":"k3d4","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3d3","text":"Customizable Tinnitus Relief: Multiflex Tinnitus Technology enables superior  flexibility in fine-tuning a relieving sound stimulus for each individual.","marks":[]}]},{"_type":"block","_key":"k3d6","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k3d5","text":"Assistive Listening Devices & Technology by Starkey","marks":[]}]},{"_type":"block","_key":"k3d8","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3d7","text":"Mini Remote Microphone","marks":[]}]},{"_type":"block","_key":"k3da","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3d9","text":"Remote Mic +","marks":[]}]},{"_type":"block","_key":"k3dc","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3db","text":"Remote Control 2.0","marks":[]}]},{"_type":"block","_key":"k3de","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3dd","text":"Table Microphone","marks":[]}]},{"_type":"block","_key":"k3dg","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3df","text":"TV Streamer","marks":[]}]},{"_type":"block","_key":"k3di","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k3dh","text":"Older Starkey Hearing Aid Models Supported By New Leaf Hearing Care In Colorado","marks":[]}]},{"_type":"block","_key":"k3dk","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3dj","text":"These hearing aid models may still be supported for hearing aid servicing and repair by New Leaf Hearing Care in Arvada, CO and Littleton, CO. Please contact us for more information.","marks":[]}]},{"_type":"block","_key":"k3dm","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3dl","text":"Starkey Picasso","marks":[]}]},{"_type":"block","_key":"k3do","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3dn","text":"Starkey Livio","marks":[]}]},{"_type":"block","_key":"k3dq","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3dp","text":"Starkey Muse iQ","marks":[]}]},{"_type":"block","_key":"k3ds","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3dr","text":"Starkey Halo iQ","marks":[]}]},{"_type":"block","_key":"k3du","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3dt","text":"Starkey Halo 2","marks":[]}]},{"_type":"block","_key":"k3dw","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3dv","text":"Starkey Halo","marks":[]}]},{"_type":"block","_key":"k3dy","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k3dx","text":"Frequently Asked Questions About Starkey Hearing Aids","marks":[]}]},{"_type":"block","_key":"k3e0","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k3dz","text":"What are the tech levels of Starkey Genesis AI?","marks":[]}]},{"_type":"block","_key":"k3e2","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3e1","text":"There are four technology levels for most of the available styles (24, 20, 16, 12) ranging from highest to lowest technology level, respectively. A contralateral routing of signal (CROS) model is also available for those with severe single-sided hearing loss.","marks":[]}]},{"_type":"block","_key":"k3e4","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k3e3","text":"What app does Starkey Genesis AI use?","marks":[]}]},{"_type":"block","_key":"k3e6","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3e5","text":"The My Starkey app pairs with Genesis AI hearing aids to help you enjoy greater listening moments, improved well-being, and easier everyday living — all at the convenience of your fingertips. User-friendly and easy to read, it delivers benefits that allow you to hear your best in a multitude of listening scenarios.","marks":[]}]},{"_type":"block","_key":"k3e8","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k3e7","text":"What is the life expectancy of a Starkey hearing aid?","marks":[]}]},{"_type":"block","_key":"k3ea","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3e9","text":"Generally speaking, in-the-ear hearing aids tend to last up to five years, while behind-the-ear hearing aids typically last five to six years. Largely, it depends on how well you take care of your hearing aids. Some patients will decide to upgrade their hearing aids prior to this time, as newer technology is routinely released and may provide greater benefits. An audiologist will be able to guide you in deciding when an upgrade is necessary.","marks":[]}]}]';
UPDATE ec_hearing_aids SET content='[{"_type":"block","_key":"k3jg","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k3jf","text":"Widex Hearing Aids Available In Colorado","marks":[]}]},{"_type":"block","_key":"q4w000","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"q4w001","text":"Widex Allure AI","marks":[]}]},{"_type":"block","_key":"q4w002","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"q4w003","text":"The Widex Allure AI RIC is Widex’s first AI-powered hearing aid. It builds on Widex’s natural sound with a dedicated AI co-processor that the wearer switches on when they want extra help in noisy places. Everyday listening stays natural and clear, and AI support is there on demand when conversations get harder to follow.","marks":[]}]},{"_type":"block","_key":"q4w004","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"q4w005","text":"The Allure AI RIC is a rechargeable receiver-in-canal (RIC) hearing aid in the same modern design as the standard Allure RIC, available in 10 colors. It offers up to 32 hours of battery life and connects to iPhone and Android devices.","marks":[]}]},{"_type":"block","_key":"q4w006","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"q4w007","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"q4w008","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"q4w009","text":"Clarity Boost with AI co-processor: A dedicated AI chip that the wearer activates in noisy environments for clearer conversations while staying aware of surrounding sounds.","marks":[]}],"listItem":"bullet","level":1},{"_type":"block","_key":"q4w00a","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"q4w00b","text":"Natural sound foundation: The W1 chip and Precision Hearing Technology deliver Widex’s signature natural sound for everyday listening.","marks":[]}],"listItem":"bullet","level":1},{"_type":"block","_key":"q4w00c","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"q4w00d","text":"Proven speech clarity: Up to 26% better speech intelligibility for moderate-to-severe hearing loss, with 97% of wearers describing the sound as natural and clear.","marks":[]}],"listItem":"bullet","level":1},{"_type":"block","_key":"q4w00e","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"q4w00f","text":"All-day rechargeable power: Up to 32 hours of use per charge, including 6 hours of AI use or streaming.","marks":[]}],"listItem":"bullet","level":1},{"_type":"block","_key":"q4w00g","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"q4w00h","text":"Flexible connectivity: Stream calls and audio through mFi, ASHA, and LE Audio, with telecoil and hands-free calling built in.","marks":[]}],"listItem":"bullet","level":1},{"_type":"block","_key":"q4w00i","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"q4w00j","text":"Charging options for every lifestyle: Choose from standard, Charge & Clean, or portable Qi-enabled wireless charging.","marks":[]}],"listItem":"bullet","level":1},{"_type":"block","_key":"k3ji","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k3jh","text":"Widex Allure","marks":[]}]},{"_type":"block","_key":"k3jk","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3jj","text":"The Widex Allure carries the brand’s most advanced hearing aid platform, offering the perfect blend of cutting-edge technology and elegant design. It is crafted to deliver the most natural hearing experience possible, helping you reconnect with the world through clear speech, accurate environmental sound processing, and intuitive adjustments.","marks":[]}]},{"_type":"block","_key":"k3jm","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3jl","text":"Unique Perks and Features:","marks":[]}]},{"_type":"block","_key":"k3jo","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3jn","text":"Powered by the W1 Chip: Widex’s fastest chip delivers quick, clear, and natural sound.","marks":[]}]},{"_type":"block","_key":"k3jq","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3jp","text":"Allure PureSound™ with ZeroDelay Technology: Helps you hear speech without distortion or echo, creating a more lifelike experience.","marks":[]}]},{"_type":"block","_key":"k3js","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3jr","text":"Speech Enhancer Pro: Lowers background noise so voices stand out, making conversations easier—even in noisy places.","marks":[]}]},{"_type":"block","_key":"k3ju","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3jt","text":"Dynamic Feedback Controller: Adapts to your ear’s shape to reduce annoying whistling or squealing sounds.","marks":[]}]},{"_type":"block","_key":"k3jw","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3jv","text":"Smooth Streaming: Enjoy music, podcasts, and calls with steady sound—no sudden volume changes or outside interference.","marks":[]}]},{"_type":"block","_key":"k3jy","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3jx","text":"Widex Allure App: Easily adjust settings and personalize your hearing experience right from your smartphone.","marks":[]}]},{"_type":"block","_key":"k3k0","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k3jz","text":"Widex SmartRIC","marks":[]}]},{"_type":"block","_key":"k3k2","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3k1","text":"Widex SmartRIC is a revolutionary hearing aid engineered for optimal performance in challenging environments. Featuring a unique L-shape design, it sits comfortably higher on the ear, amplifying conversations even in noisy surroundings. With an impressive battery life of up to 37 hours, you can enjoy uninterrupted hearing throughout your day.","marks":[]}]},{"_type":"block","_key":"k3k4","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3k3","text":"The accompanying portable charger provides over a week’s worth of power for on-the-go convenience, ensuring you never miss a moment. Plus, its advanced microphone cover effectively minimizes irritating background noise and distractions, allowing for clearer and more focused hearing.","marks":[]}]},{"_type":"block","_key":"k3k6","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3k5","text":"Unique Perks and Features:","marks":[]}]},{"_type":"block","_key":"k3k8","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3k7","text":"App: The SmartRIC works with the Moment app to let you adjust your sound settings just the way you like. The app uses special technology to make changes based on your preferences and surroundings, giving you a better listening experience.","marks":[]}]},{"_type":"block","_key":"k3ka","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3k9","text":"Bluetooth: You can connect and stream sounds from both iPhone and Android devices.","marks":[]}]},{"_type":"block","_key":"k3kc","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3kb","text":"Tinnitus Relief: The SmartRIC offers help for tinnitus through Zen programs. These programs use relaxing tones and sounds to help reduce the ringing in your ears.","marks":[]}]},{"_type":"block","_key":"k3ke","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k3kd","text":"Widex Moment Sheer RIC","marks":[]}]},{"_type":"block","_key":"k3kg","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3kf","text":"The Widex Moment Sheer receiver-in-the-canal (RIC) hearing aid offers an updated sleek design with new microphone placement in addition to the redesigned charger. Additionally, Widex offers unique solutions to give patients freedom at their fingertips in the Widex app. Dual Artificial Intelligence (AI) allows for more personalization and control in the patient’s hands.","marks":[]}]},{"_type":"block","_key":"k3ki","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3kh","text":"Widex Moment Sheer RIC products are appropriate for minimal to severe-to-profound hearing losses. There is an option for either a rechargeable or a disposable battery. Widex reports their battery time is approximately 29 hours with no streaming or 16 hours with 8 hours of streaming.","marks":[]}]},{"_type":"block","_key":"k3kk","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3kj","text":"Unique Perks and Features:","marks":[]}]},{"_type":"block","_key":"k3km","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3kl","text":"Bluetooth: Connectivity and streaming are available for both iPhone & Android devices.","marks":[]}]},{"_type":"block","_key":"k3ko","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3kn","text":"App: The Widex Moment app offers “Made for You” and “Create Your Own” features, which allow you to customize your hearing aid fitting.","marks":[]}]},{"_type":"block","_key":"k3kq","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3kp","text":"Tinnitus Relief: Tinnitus management is available in the Zen programs, which aim to reduce tinnitus perception by utilizing fractal tones, sounds, and other masking choices.","marks":[]}]},{"_type":"block","_key":"k3ks","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k3kr","text":"Widex Moment RIC","marks":[]}]},{"_type":"block","_key":"k3ku","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3kt","text":"The Widex Moment receiver-in-the-canal (RIC) hearing aid offers a discreet design, natural sound quality, and direct audio streaming. Their updated sound processing provides patients with rapid, accurate, high-fidelity sound. Researchers found that overall, 91% of respondents were satisfied with the Moment sound quality. When it came to speech-in-noise, five times as many participants were satisfied with Moment compared to their own hearing aids. A total of 90% were satisfied with how the Moment devices functioned in their daily life!","marks":[]}]},{"_type":"block","_key":"k3kw","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3kv","text":"Widex Moment RIC products are appropriate for fitting minimal to severe-to-profound hearing losses. There is an option for either rechargeable or various disposable battery-size solutions.","marks":[]}]},{"_type":"block","_key":"k3ky","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3kx","text":"Unique Perks and Features:","marks":[]}]},{"_type":"block","_key":"k3l0","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3kz","text":"Bluetooth: Connectivity and streaming are available for both iPhone & Android devices.","marks":[]}]},{"_type":"block","_key":"k3l2","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3l1","text":"App: The Widex Moment app offers “Made for You” and “Create Your Own” features, which allow you to customize your hearing aid fitting.","marks":[]}]},{"_type":"block","_key":"k3l4","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3l3","text":"Tinnitus Relief: Tinnitus management is available in the Zen programs, which aim to reduce tinnitus perception by utilizing fractal tones, sounds, and other masking choices.","marks":[]}]},{"_type":"block","_key":"k3l6","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k3l5","text":"Widex Moment BTE","marks":[]}]},{"_type":"block","_key":"k3l8","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3l7","text":"For years, Widex has used artificial intelligence in its hearing aid technologies to help improve its sound quality. Over time, by learning what patients prefer to hear, they’ve crafted technology that helps predict what you will want to hear.","marks":[]}]},{"_type":"block","_key":"k3la","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3l9","text":"SoundSense Learn is their proprietary hearing aid feature that’s based on the deeper artificial intelligence (AI) form, Machine Learning. This tool calculates the best possible hearing settings at the precise moment based on input from the user. As SoundSense Learn gets smarter, it continues to get faster at calculating the best sound for each individual.","marks":[]}]},{"_type":"block","_key":"k3lc","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3lb","text":"Widex Moment is available in the behind-the-ear (BTE) style and is appropriate for fitting minimal to severe-to-profound hearing losses. There is an option for either a rechargeable or a size 13 disposable battery.","marks":[]}]},{"_type":"block","_key":"k3le","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3ld","text":"Unique Perks and Features:","marks":[]}]},{"_type":"block","_key":"k3lg","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3lf","text":"Bluetooth: Connectivity and streaming are available for both iPhone & Android devices.","marks":[]}]},{"_type":"block","_key":"k3li","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3lh","text":"App: The Widex Moment app offers “Made for You” and “Create Your Own” features, which allow you to customize your hearing aid fitting.","marks":[]}]},{"_type":"block","_key":"k3lk","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3lj","text":"Tinnitus Relief: Tinnitus management is available in the Zen programs, which aim to reduce tinnitus perception by utilizing fractal tones, sounds, and other masking choices.","marks":[]}]},{"_type":"block","_key":"k3lm","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k3ll","text":"Widex Moment CROS","marks":[]}]},{"_type":"block","_key":"k3lo","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3ln","text":"Not all hearing aids are created equally, and Widex has been a leader in the hearing aid industry when it comes to its contralateral routing of the signal (CROS) technology. Single-sided deafness can create several listening challenges, including sound localization and listening in background noise.","marks":[]}]},{"_type":"block","_key":"k3lq","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3lp","text":"The Widex CROS provides a solution for individuals who are looking for superb sound quality with minimal distortion or echo. A CROS operates by wearing a transmitter on the poorer-hearing ear, and sounds received from that transmitter are wirelessly routed to a hearing device on the better-hearing ear.","marks":[]}]},{"_type":"block","_key":"k3ls","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3lr","text":"The Widex CROS is designed for individuals with one-sided hearing loss, or single-sided deafness (SSD). The device can be fitted as either a true CROS or BiCROS (hearing loss is also in the better hearing ear).","marks":[]}]},{"_type":"block","_key":"k3lu","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3lt","text":"Widex offers advanced battery-saving solutions, reportedly using three times less power than other wireless CROS solutions.","marks":[]}]},{"_type":"block","_key":"k3lw","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3lv","text":"The CROS is currently compatible with the EVOKE family of hearing aids.","marks":[]}]},{"_type":"block","_key":"k3ly","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3lx","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"k3m0","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3lz","text":"Superior Sound Quality: Provides superb sound quality with minimal distortion or echo.","marks":[]}]},{"_type":"block","_key":"k3m2","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3m1","text":"Wireless Audio Routing: Transmits sounds from the poorer-hearing ear to the better-hearing ear wirelessly.","marks":[]}]},{"_type":"block","_key":"k3m4","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3m3","text":"Versatile Fitting Options: Can be fitted as either a true CROS or BiCROS, catering to various hearing loss needs.","marks":[]}]},{"_type":"block","_key":"k3m6","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3m5","text":"Advanced Battery Efficiency: Uses three times less power than other wireless CROS solutions.","marks":[]}]},{"_type":"block","_key":"k3m8","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3m7","text":"Compatibility: Compatible with the EVOKE family hearing aids.","marks":[]}]},{"_type":"block","_key":"k3ma","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k3m9","text":"Widex Moment ITE","marks":[]}]},{"_type":"block","_key":"k3mc","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3mb","text":"Ensuring a perfect fit isn’t always easy, but Widex’s custom in-the-ear (ITE) devices allow you to craft a hearing aid that fits true to your specific ear anatomy. All Widex ITE hearing aids and completely-in-canal (CIC) hearing aids are fully automatic. This allows you to hear clear and natural sounds with minimal intervention.","marks":[]}]},{"_type":"block","_key":"k3me","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3md","text":"Widex Moment ITE products are appropriate for minimal to moderately severe hearing loss. There is an option for size 10 or 312 disposable batteries. The anticipated battery life varies greatly depending on the severity of the hearing loss, usage, and streaming frequency. Widex shares that the average usage can range between 105 and 150 hours.","marks":[]}]},{"_type":"block","_key":"k3mg","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3mf","text":"Unique Perks and Features:","marks":[]}]},{"_type":"block","_key":"k3mi","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3mh","text":"Tailored Fit: Custom products that are designed to be tailored to your ear anatomy","marks":[]}]},{"_type":"block","_key":"k3mk","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3mj","text":"Connectivity: Streaming and Bluetooth are available to control programs and volume with a DEX device or the TONELINK™ app.","marks":[]}]},{"_type":"block","_key":"k3mm","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3ml","text":"Tinnitus Relief: Tinnitus management is available in the Zen programs, which aim to reduce tinnitus perception by utilizing fractal tones, sounds, and other masking options","marks":[]}]},{"_type":"block","_key":"k3mo","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k3mn","text":"Assistive Listening Devices & Technology by Widex","marks":[]}]},{"_type":"block","_key":"k3mq","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k3mp","text":"Widex TV Play","marks":[]}]},{"_type":"block","_key":"k3ms","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3mr","text":"Widex Moment™ devices connect seamlessly with TV Play. This means you can stream the sound of your TV directly to your hearing aids with incredibly natural sound quality. This makes TV, movies, and games truly immersive and more enjoyable.","marks":[]}]},{"_type":"block","_key":"k3mu","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k3mt","text":"Widex Sound Assist™","marks":[]}]},{"_type":"block","_key":"k3mw","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3mv","text":"This product connects to your hearing aids to provide a tabletop microphone, hands-free, and remote-control functionality. Some scenarios where this can come in handy include partner conversations in noise, table microphone use in a busy dining room, group conversations, hands-free phone calls, and more.","marks":[]}]},{"_type":"block","_key":"k3my","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3mx","text":"Widex Sound Assist","marks":[]}]},{"_type":"block","_key":"k3n0","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3mz","text":"Com-Dex","marks":[]}]},{"_type":"block","_key":"k3n2","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3n1","text":"RC-Dex","marks":[]}]},{"_type":"block","_key":"k3n4","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3n3","text":"TV-Dex","marks":[]}]},{"_type":"block","_key":"k3n6","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k3n5","text":"Older Widex Hearing Aid Models Supported By New Leaf Hearing Care","marks":[]}]},{"_type":"block","_key":"k3n8","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3n7","text":"These hearing aid models may still be supported for hearing aid servicing and repair by New Leaf Hearing Care in Arvada, CO and Littleton, CO. Please contact us for more information.","marks":[]}]},{"_type":"block","_key":"k3na","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3n9","text":"Widex Evoke","marks":[]}]},{"_type":"block","_key":"k3nc","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3nb","text":"Widex Beyond","marks":[]}]},{"_type":"block","_key":"k3ne","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3nd","text":"Widex Unique","marks":[]}]},{"_type":"block","_key":"k3ng","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3nf","text":"Widex Dream","marks":[]}]},{"_type":"block","_key":"k3ni","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k3nh","text":"Frequently Asked Questions About Widex Hearing Aids","marks":[]}]},{"_type":"block","_key":"k3nk","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k3nj","text":"What is the top-of-the-line Widex hearing aid?","marks":[]}]},{"_type":"block","_key":"k3nm","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3nl","text":"Widex Moment Sheer 440 is the top technology level available in the line. The 440 comes with a complete set of sound processing features, including wind noise reduction, speech enhancement, and 15 adjustment bands of customization for your audiologist.","marks":[]}]},{"_type":"block","_key":"k3no","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k3nn","text":"What are the levels of Widex Moment?","marks":[]}]},{"_type":"block","_key":"k3nq","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3np","text":"There are three levels available in the Widex Moment platform:","marks":[]}]},{"_type":"block","_key":"k3ns","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3nr","text":"Widex Moment 220: Basic Level","marks":[]}]},{"_type":"block","_key":"k3nu","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3nt","text":"Widex Moment 330: Standard Level","marks":[]}]},{"_type":"block","_key":"k3nw","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3nv","text":"Widex Moment 440: Premium Level","marks":[]}]},{"_type":"block","_key":"k3ny","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k3nx","text":"Is Widex Moment good for tinnitus?","marks":[]}]},{"_type":"block","_key":"k3o0","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3nz","text":"Yes, the Widex Moment™ app provides access to your tinnitus solution to help manage your tinnitus, relaxation, well-being, and concentration. The Widex app offers “Made for You” and “Create Your Own” features for Moment devices, which allow you to customize your hearing aid fitting.","marks":[]}]}]', updated_at=datetime('now') WHERE slug='widex-hearing-aids' AND content='[{"_type":"block","_key":"k3jg","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k3jf","text":"Widex Hearing Aids Available In Colorado","marks":[]}]},{"_type":"block","_key":"k3ji","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k3jh","text":"Widex Allure","marks":[]}]},{"_type":"block","_key":"k3jk","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3jj","text":"The Widex Allure carries the brand’s most advanced hearing aid platform, offering the perfect blend of cutting-edge technology and elegant design. It is crafted to deliver the most natural hearing experience possible, helping you reconnect with the world through clear speech, accurate environmental sound processing, and intuitive adjustments.","marks":[]}]},{"_type":"block","_key":"k3jm","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3jl","text":"Unique Perks and Features:","marks":[]}]},{"_type":"block","_key":"k3jo","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3jn","text":"Powered by the W1 Chip: Widex’s fastest chip delivers quick, clear, and natural sound.","marks":[]}]},{"_type":"block","_key":"k3jq","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3jp","text":"Allure PureSound™ with ZeroDelay Technology: Helps you hear speech without distortion or echo, creating a more lifelike experience.","marks":[]}]},{"_type":"block","_key":"k3js","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3jr","text":"Speech Enhancer Pro: Lowers background noise so voices stand out, making conversations easier—even in noisy places.","marks":[]}]},{"_type":"block","_key":"k3ju","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3jt","text":"Dynamic Feedback Controller: Adapts to your ear’s shape to reduce annoying whistling or squealing sounds.","marks":[]}]},{"_type":"block","_key":"k3jw","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3jv","text":"Smooth Streaming: Enjoy music, podcasts, and calls with steady sound—no sudden volume changes or outside interference.","marks":[]}]},{"_type":"block","_key":"k3jy","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3jx","text":"Widex Allure App: Easily adjust settings and personalize your hearing experience right from your smartphone.","marks":[]}]},{"_type":"block","_key":"k3k0","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k3jz","text":"Widex SmartRIC","marks":[]}]},{"_type":"block","_key":"k3k2","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3k1","text":"Widex SmartRIC is a revolutionary hearing aid engineered for optimal performance in challenging environments. Featuring a unique L-shape design, it sits comfortably higher on the ear, amplifying conversations even in noisy surroundings. With an impressive battery life of up to 37 hours, you can enjoy uninterrupted hearing throughout your day.","marks":[]}]},{"_type":"block","_key":"k3k4","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3k3","text":"The accompanying portable charger provides over a week’s worth of power for on-the-go convenience, ensuring you never miss a moment. Plus, its advanced microphone cover effectively minimizes irritating background noise and distractions, allowing for clearer and more focused hearing.","marks":[]}]},{"_type":"block","_key":"k3k6","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3k5","text":"Unique Perks and Features:","marks":[]}]},{"_type":"block","_key":"k3k8","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3k7","text":"App: The SmartRIC works with the Moment app to let you adjust your sound settings just the way you like. The app uses special technology to make changes based on your preferences and surroundings, giving you a better listening experience.","marks":[]}]},{"_type":"block","_key":"k3ka","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3k9","text":"Bluetooth: You can connect and stream sounds from both iPhone and Android devices.","marks":[]}]},{"_type":"block","_key":"k3kc","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3kb","text":"Tinnitus Relief: The SmartRIC offers help for tinnitus through Zen programs. These programs use relaxing tones and sounds to help reduce the ringing in your ears.","marks":[]}]},{"_type":"block","_key":"k3ke","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k3kd","text":"Widex Moment Sheer RIC","marks":[]}]},{"_type":"block","_key":"k3kg","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3kf","text":"The Widex Moment Sheer receiver-in-the-canal (RIC) hearing aid offers an updated sleek design with new microphone placement in addition to the redesigned charger. Additionally, Widex offers unique solutions to give patients freedom at their fingertips in the Widex app. Dual Artificial Intelligence (AI) allows for more personalization and control in the patient’s hands.","marks":[]}]},{"_type":"block","_key":"k3ki","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3kh","text":"Widex Moment Sheer RIC products are appropriate for minimal to severe-to-profound hearing losses. There is an option for either a rechargeable or a disposable battery. Widex reports their battery time is approximately 29 hours with no streaming or 16 hours with 8 hours of streaming.","marks":[]}]},{"_type":"block","_key":"k3kk","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3kj","text":"Unique Perks and Features:","marks":[]}]},{"_type":"block","_key":"k3km","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3kl","text":"Bluetooth: Connectivity and streaming are available for both iPhone & Android devices.","marks":[]}]},{"_type":"block","_key":"k3ko","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3kn","text":"App: The Widex Moment app offers “Made for You” and “Create Your Own” features, which allow you to customize your hearing aid fitting.","marks":[]}]},{"_type":"block","_key":"k3kq","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3kp","text":"Tinnitus Relief: Tinnitus management is available in the Zen programs, which aim to reduce tinnitus perception by utilizing fractal tones, sounds, and other masking choices.","marks":[]}]},{"_type":"block","_key":"k3ks","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k3kr","text":"Widex Moment RIC","marks":[]}]},{"_type":"block","_key":"k3ku","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3kt","text":"The Widex Moment receiver-in-the-canal (RIC) hearing aid offers a discreet design, natural sound quality, and direct audio streaming. Their updated sound processing provides patients with rapid, accurate, high-fidelity sound. Researchers found that overall, 91% of respondents were satisfied with the Moment sound quality. When it came to speech-in-noise, five times as many participants were satisfied with Moment compared to their own hearing aids. A total of 90% were satisfied with how the Moment devices functioned in their daily life!","marks":[]}]},{"_type":"block","_key":"k3kw","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3kv","text":"Widex Moment RIC products are appropriate for fitting minimal to severe-to-profound hearing losses. There is an option for either rechargeable or various disposable battery-size solutions.","marks":[]}]},{"_type":"block","_key":"k3ky","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3kx","text":"Unique Perks and Features:","marks":[]}]},{"_type":"block","_key":"k3l0","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3kz","text":"Bluetooth: Connectivity and streaming are available for both iPhone & Android devices.","marks":[]}]},{"_type":"block","_key":"k3l2","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3l1","text":"App: The Widex Moment app offers “Made for You” and “Create Your Own” features, which allow you to customize your hearing aid fitting.","marks":[]}]},{"_type":"block","_key":"k3l4","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3l3","text":"Tinnitus Relief: Tinnitus management is available in the Zen programs, which aim to reduce tinnitus perception by utilizing fractal tones, sounds, and other masking choices.","marks":[]}]},{"_type":"block","_key":"k3l6","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k3l5","text":"Widex Moment BTE","marks":[]}]},{"_type":"block","_key":"k3l8","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3l7","text":"For years, Widex has used artificial intelligence in its hearing aid technologies to help improve its sound quality. Over time, by learning what patients prefer to hear, they’ve crafted technology that helps predict what you will want to hear.","marks":[]}]},{"_type":"block","_key":"k3la","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3l9","text":"SoundSense Learn is their proprietary hearing aid feature that’s based on the deeper artificial intelligence (AI) form, Machine Learning. This tool calculates the best possible hearing settings at the precise moment based on input from the user. As SoundSense Learn gets smarter, it continues to get faster at calculating the best sound for each individual.","marks":[]}]},{"_type":"block","_key":"k3lc","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3lb","text":"Widex Moment is available in the behind-the-ear (BTE) style and is appropriate for fitting minimal to severe-to-profound hearing losses. There is an option for either a rechargeable or a size 13 disposable battery.","marks":[]}]},{"_type":"block","_key":"k3le","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3ld","text":"Unique Perks and Features:","marks":[]}]},{"_type":"block","_key":"k3lg","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3lf","text":"Bluetooth: Connectivity and streaming are available for both iPhone & Android devices.","marks":[]}]},{"_type":"block","_key":"k3li","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3lh","text":"App: The Widex Moment app offers “Made for You” and “Create Your Own” features, which allow you to customize your hearing aid fitting.","marks":[]}]},{"_type":"block","_key":"k3lk","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3lj","text":"Tinnitus Relief: Tinnitus management is available in the Zen programs, which aim to reduce tinnitus perception by utili